<?php
session_start(); require_once __DIR__ . "/config.php"; require_admin();
$customerCount=(int)$conn->query("SELECT COUNT(*) n FROM customers")->fetch_assoc()["n"];
$paymentCount=(int)$conn->query("SELECT COUNT(*) n FROM rd_payments")->fetch_assoc()["n"];
$total=(float)$conn->query("SELECT COALESCE(SUM(amount),0) n FROM rd_payments")->fetch_assoc()["n"];
$monthly=$conn->query("SELECT DATE_FORMAT(payment_month,'%Y-%m') month_label,COUNT(*) payment_count,SUM(amount) total FROM rd_payments GROUP BY DATE_FORMAT(payment_month,'%Y-%m') ORDER BY month_label DESC");
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><style>body{font-family:Arial;background:#f1f5f9;padding:18px}main{background:white;padding:20px;border-radius:12px;max-width:900px;margin:auto}.stats{display:flex;gap:12px;flex-wrap:wrap}.card{padding:16px;background:#eff6ff;border-radius:8px;flex:1;min-width:150px}table{width:100%;border-collapse:collapse;margin-top:15px}td,th{padding:10px;border:1px solid #ddd}th{background:#123b70;color:white}</style></head><body><main><h2>Reports</h2><div class="stats"><div class="card">Customers<br><b><?= $customerCount ?></b></div><div class="card">Payment entries<br><b><?= $paymentCount ?></b></div><div class="card">Total collected<br><b>₹<?= number_format($total,2) ?></b></div></div><h3>Month-wise Collection</h3><table><tr><th>Month</th><th>Payment Entries</th><th>Total Collected</th></tr><?php while($r=$monthly->fetch_assoc()): ?><tr><td><?= htmlspecialchars($r["month_label"]) ?></td><td><?= (int)$r["payment_count"] ?></td><td>₹<?= number_format((float)$r["total"],2) ?></td></tr><?php endwhile; ?></table><p><a href="dashboard.php">← Dashboard</a> | <a href="payment_history.php">Payment History</a></p><button onclick="window.print()">Print Report</button></main></body></html>